def intercalar(a, b):
    r = []
    i = 0
    j = 0
    while i < len(a) and j < len(b):
        if a[i] <= b[j]:
            r.append(a[i])
            i += 1
        else:
            r.append(b[j])
            j += 1
    return r + a[i:] + b[j:]


def merge_sort(v):
    if len(v) <= 1:
        return v
    meio = len(v) // 2
    return intercalar(merge_sort(v[:meio]), merge_sort(v[meio:]))


def busca(v, alvo):
    ini = 0
    fim = len(v)
    while ini < fim:
        meio = (ini + fim) // 2
        if v[meio] < alvo:
            ini = meio + 1
        else:
            fim = meio
    if ini < len(v) and v[ini] == alvo:
        return ini
    return -1


