import math


class Forma:
    def __init__(self, nome):
        self.nome = nome

    def area(self):
        raise NotImplementedError

    def perimetro(self):
        raise NotImplementedError

    def descricao(self):
        return f"{self.nome}: área {self.area():.2f}, perímetro {self.perimetro():.2f}"


class Retangulo(Forma):
    def __init__(self, largura, altura):
        super().__init__("Retângulo")
        self.largura = largura
        self.altura = altura

    def area(self):
        return self.largura * self.altura

    def perimetro(self):
        return 2 * (self.largura + self.altura)


class Circulo(Forma):
    def __init__(self, raio):
        super().__init__("Círculo")
        self.raio = raio

    def area(self):
        return math.pi * self.raio ** 2

    def perimetro(self):
        return 2 * math.pi * self.raio


class Triangulo(Forma):
    def __init__(self, a, b, c):
        if a >= b + c or b >= a + c or c >= a + b:
            raise ValueError("triângulo inválido")
        super().__init__("Triângulo")
        self.a = a
        self.b = b
        self.c = c

    def area(self):
        s = (self.a + self.b + self.c) / 2
        return math.sqrt(s * (s - self.a) * (s - self.b) * (s - self.c))

    def perimetro(self):
        return self.a + self.b + self.c


tipos = {"retangulo": Retangulo, "circulo": Circulo, "triangulo": Triangulo}

n = int(input())
formas = []
for i in range(n):
    partes = input().split()
    if partes[0] not in tipos:
        print(f"Erro: forma desconhecida '{partes[0]}'")
        continue
    medidas = [float(x) for x in partes[1:]]
    try:
        f = tipos[partes[0]](*medidas)
    except ValueError as e:
        print(f"Erro: {e}")
        continue
    formas.append(f)
    print(f.descricao())
total = sum(f.area() for f in formas)
print(f"Área total: {total:.2f}")
print(f"Maior área: {max(formas, key=lambda f: f.area()).nome}")

