def conta_chamadas(func):
    def embalagem(*args):
        embalagem.chamadas += 1
        return func(*args)
    embalagem.chamadas = 0
    return embalagem


def memoriza(func):
    cache = {}
    def embalagem(*args):
        if args not in cache:
            cache[args] = func(*args)
        return cache[args]
    return embalagem


