lessons.solution:
class ErroSintaxe(Exception):
    pass


def tokenizar(texto):
    tokens = []
    i = 0
    while i < len(texto):
        c = texto[i]
        if c.isdigit():
            j = i
            while j < len(texto) and texto[j].isdigit():
                j += 1
            tokens.append(texto[i:j])
            i = j
        elif c in "+-*/()":
            tokens.append(c)
            i += 1
        elif c == " ":
            i += 1
        else:
            raise ErroSintaxe()
    return tokens


class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def olhar(self):
        if self.pos < len(self.tokens):
            return self.tokens[self.pos]
        return None

    def consumir(self):
        t = self.olhar()
        if t is None:
            raise ErroSintaxe()
        self.pos += 1
        return t

    def expressao(self):
        valor = self.termo()
        while self.olhar() in ("+", "-"):
            op = self.consumir()
            direita = self.termo()
            valor = valor + direita if op == "+" else valor - direita
        return valor

    def termo(self):
        valor = self.fator()
        while self.olhar() in ("*", "/"):
            op = self.consumir()
            direita = self.fator()
            if op == "*":
                valor = valor * direita
            else:
                valor = valor // direita
        return valor

    def fator(self):
        t = self.consumir()
        if t == "(":
            valor = self.expressao()
            if self.consumir() != ")":
                raise ErroSintaxe()
            return valor
        if t == "-":
            return -self.fator()
        if t.isdigit():
            return int(t)
        raise ErroSintaxe()


def avaliar(texto):
    p = Parser(tokenizar(texto))
    valor = p.expressao()
    if p.olhar() is not None:
        raise ErroSintaxe()
    return valor


n = int(input())
for i in range(n):
    texto = input()
    try:
        print(avaliar(texto))
    except ErroSintaxe:
        print("Erro de sintaxe")
    except ZeroDivisionError:
        print("Erro: divisão por zero")

