import heapq

N, M = [int(x) for x in input().split()]
adj = {v: [] for v in range(1, N + 1)}
for i in range(M):
    u, v, w = [int(x) for x in input().split()]
    adj[u].append((v, w))
    adj[v].append((u, w))
s = int(input())

INF = float("inf")
dist = {v: INF for v in adj}
dist[s] = 0
heap = [(0, s)]
while heap:
    d, u = heapq.heappop(heap)
    if d > dist[u]:
        continue
    for v, w in adj[u]:
        if d + w < dist[v]:
            dist[v] = d + w
            heapq.heappush(heap, (dist[v], v))

for v in range(1, N + 1):
    if dist[v] == INF:
        print(f"{v}: inalcançável")
    else:
        print(f"{v}: {dist[v]}")

def distancia(a, b):
    n = len(a)
    m = len(b)
    D = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        D[i][0] = i
    for j in range(m + 1):
        D[0][j] = j
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                D[i][j] = D[i - 1][j - 1]
            else:
                D[i][j] = 1 + min(D[i - 1][j - 1], D[i - 1][j], D[i][j - 1])
    return D[n][m]


def lcs(a, b):
    n = len(a)
    m = len(b)
    L = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if a[i - 1] == b[j - 1]:
                L[i][j] = L[i - 1][j - 1] + 1
            else:
                L[i][j] = max(L[i - 1][j], L[i][j - 1])
    return L[n][m]


n = int(input())
for k in range(n):
    p1, p2 = input().split()
    a = "" if p1 == "-" else p1
    b = "" if p2 == "-" else p2
    print(f"{p1} -> {p2}: distância {distancia(a, b)}, LCS {lcs(a, b)}")
